 import unittest
from candidate import remove_vowels

class TestRemoveVowels(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(remove_vowels(""), "")

    def test_string_without_vowels(self):
        self.assertEqual(remove_vowels("abcdef\nghijklm"), "bcdf\nghjklm")

    def test_string_with_only_vowels(self):
        self.assertEqual(remove_vowels("aaaaa"), "")

    def test_string_with_mixed_vowels_and_consonants(self):
        self.assertEqual(remove_vowels("aaBAA"), "B")

    def test_string_with_only_consonants(self):
        self.assertEqual(remove_vowels("zbcd"), "zbcd")

    def test_string_with_uppercase_vowels(self):
        self.assertEqual(remove_vowels("AEIOUaeiou"), "")

    def test_string_with_punctuation(self):
        self.assertEqual(remove_vowels("abcdef!ghijklm."), "bcdf!ghjklm.")

    def test_string_with_numbers(self):
        self.assertEqual(remove_vowels("abc123def"), "bc123d")

    def test_string_with_multiple_spaces(self):
        self.assertEqual(remove_vowels(" abc def ghi "), " bcd ghi ")

    def test_string_with_single_space(self):
        self.assertEqual(remove_vowels("ab cd ef"), "bc de")

    def test_string_with_leading_trailing_spaces(self):
        self.assertEqual(remove_vowels(" ab cd ef gh "), "bc de gh")

    def test_string_with_only_vowels_and_punctuation(self):
        self.assertEqual(remove_vowels("!.,:;aeiouAEIOU"), "")

    def test_string_with_empty_characters(self):
        self.assertEqual(remove_vowels("\t\n\r"), "\t\n\r")

    def test_string_with_non_string_input(self):
        with self.assertRaises(TypeError):
            remove_vowels(123)

    def test_string_with_none_input(self):
        with self.assertRaises(TypeError):
            remove_vowels(None)

if __name__ == '__main__':
    unittest.main()
